var t=`0295-pastrmajlija`;var i=`world-0295`;var o=`MK`;var a=`southern-europe`;var r=4;var l=99;var s={en:`Pastrmajlija`,ua:`Пастрмайлія`};var u={en:`A traditional North Macedonia dish made with all-purpose flour, instant yeast, ground pork, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Північна Македонія. Основні інгредієнти: пшеничне борошно універсальне, інстантні дріжджі, свинячий фарш, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,500,`g`],[`water`,250,`ml`],[`instant-yeast`,7,`g`],[`sunflower-oil`,35,`ml`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:8,i:[[`ground-pork`,450,`g`],[`yellow-onion`,150,`g`],[`sweet-paprika`,6,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 17 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 17 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:17,i:[]}];var d={slug:t,id:i,country:`MK`,region:a,servings:4,minutes:99,title:s,text:u,steps:g};export{o as country,d as default,i as id,l as minutes,a as region,r as servings,t as slug,g as steps,u as text,s as title};